draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw ground
  ctx.beginPath();
  ctx.moveTo(0, H - 50);
  ctx.lineTo(W, H - 50);
  ctx.stroke();

  // draw carrot
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.arc(W/2, H - 75 + 20*Math.sin(t), 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw leaves
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H - 120 + 10*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 - 10, H - 110 + 10*Math.sin(t), 5, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 10, H - 110 + 10*Math.sin(t), 5, 0, 2*Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw vitamin A
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Vitamin A', W/2, H - 150 + 10*Math.sin(t));

  ctx.restore();
}
